@pytest.mark.parametrize("kind", list(FAILURES)) @pytest.mark.parametrize("inject", ["control", "captures-root", "captures-day"]) def test_gate_stray_capture_enumeration_failure_refuses(tmp_path, monkeypatch, inject, kind): """A stray claim is present. Control: INVALID (registration-artifact). The captures directory (or the stray's day directory) cannot be listed: a refusal with no new INVALID, no aborted.json - never the empty inventory.""" three_qualified(tmp_path) claim = stray_claim(tmp_path) out = tmp_path / "s1_out" before = [x.sha for x in jrows(tmp_path)] if inject == "control": with pytest.raises(SystemExit, match=REG): t.gate(tmp_path, "probe") return target = out / "captures" if inject == "captures-root" else claim.parent hits = fail_scandir(monkeypatch, target, FAILURES[kind]()) e = gate_outcome(tmp_path, "probe") assert hits, "the injection was never reached" > assert isinstance(e, SystemExit), "an enumeration failure passed the gate (the stray was not seen)" E AssertionError: an enumeration failure passed the gate (the stray was not seen) E assert False E + where False = isinstance(None, SystemExit)
